/).filter((_,i)=>!removed.has(i)).join('
');}
export function parseVideoInfo(stderr){const input=stderr.split(/Output #/)[0];const rows=[...input.matchAll(/Stream #0:(\d+)[^
]*Video:([^
]+)/g)];const streams=rows.map(m=>{const size=m[2].match(/(?:^|[ ,])(\d{2,5})x(\d{2,5})(?=[ ,\[])/);return size?{index:Number(m[1]),width:Number(size[1]),height:Number(size[2]),codec:m[2].split(',')[0].trim(),fps:Number(m[2].match(/([\d.]+) fps/)?.[1])||null}:null;}).filter(Boolean);return streams.filter(s=>s.height<=1080).sort((a,b)=>b.height-a.height||b.width-a.width)[0]||null;}
