(()=>{const section=document.createElement('details');section.innerHTML='<summary>غرفة الصوت · حتى أربعة أجهزة</summary><p>الاتصال صوتي مباشر بين الأجهزة، وقد لا يعمل خلف بعض الشبكات دون خادم TURN. قد يكشف عنوان الشبكة للمشاركين. الميكروفون مغلق بعد الدخول حتى تفعّله.</p><div class="pro-controls"><button id="voice-join">دخول غرفة الصوت</button><button id="voice-mic" disabled>فتح الميكروفون</button><button id="voice-leave" disabled>مغادرة</button><label>صوت الأصدقاء<input id="voice-volume" type="range" min="0" max="1" step="0.1" value="1"></label><button id="voice-commentary">المعلق الأصلي / صوت الأصدقاء</button></div><p id="voice-state"></p><div id="voice-peers"></div>';$('pro-tab-social').append(section);let stream=null,own='',since=0,active=false,polling=false,forcedMute=false;const peers=new Map();
