function connection(peer){if(peers.has(peer.id))return peers.get(peer.id);const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]}),audio=document.createElement('audio');audio.autoplay=true;audio.controls=true;audio.volume=Number($('voice-volume').value);audio.setAttribute('aria-label','صوت '+peer.name);const wrapper=document.createElement('div');wrapper.className='voice-person';const label=document.createElement('strong');label.textContent=peer.name;wrapper.append(label,audio);if(state.canControl){const mute=button('كتم / السماح للصديق',async()=>{const next=!p.muted;try{await api('/api/pro/voice-mute',{id:peer.id,muted:next});p.muted=next;mute.textContent=next?'السماح بالميكروفون':'كتم الصديق';}catch(e){notice(e.message);}});wrapper.append(mute);}$('voice-peers').append(wrapper);const p={pc,audio,wrapper,muted:peer.muted,candidates:[]};peers.set(peer.id,p);for(const track of stream.getTracks())pc.addTrack(track,stream);pc.onicecandidate=e=>{if(e.candidate)send('candidate',peer.id,e.candidate.toJSON()).catch(()=>{});};pc.ontrack=e=>{audio.srcObject=e.streams[0];audio.play().catch(()=>{$('voice-state').textContent='اضغط تشغيل في أداة الصوت للسماح بسماع الأصدقاء';});};pc.onconnectionstatechange=()=>{if(pc.connectionState==='failed')$('voice-state').textContent='تعذر الاتصال بمشارك؛ هذه الشبكة قد تحتاج خادم TURN';};return p;}
